"""Source-grounded replacements for the instructor's expanded sea-lion topic.

Numbers are PowerPoint slide numbers. Slides 41–43 are deliberately untouched.
"""

REFERENCES = {
    's16': ('Sawyer et al. (2016)', '10.1002/cne.23984', 'Sawyer EK, Turner EC, Kaas JH (2016). Somatosensory brainstem, thalamus, and cortex of the California sea lion (Zalophus californianus). Journal of Comparative Neurology 524(9):1957–1975.'),
    'm14': ('Milne and Grant (2014)', '10.1007/s00359-014-0931-1', 'Milne AO, Grant RA (2014). Characterisation of whisker control in the California sea lion (Zalophus californianus) during a complex, dynamic sensorimotor task. Journal of Comparative Physiology A 200:871–879.'),
    'm21': ('Milne et al. (2021)', '10.1242/jeb.243085', 'Milne AO, Orton L, Black CH, Jones GC, Sullivan M, Grant RA (2021). California sea lions employ task-specific strategies for active touch sensing. Journal of Experimental Biology 224(21):jeb243085.'),
    'l21': ('Leahy et al. (2021)', '10.1242/jeb.243020', 'Leahy AM, Fish FE, Kerr SJ, Zeligs JA, Skrovan S, Cardenas KL, Leftwich MC (2021). The role of California sea lion (Zalophus californianus) hindflippers as aquatic control surfaces for maneuverability. Journal of Experimental Biology 224(20):jeb243020.'),
    'e23': ('Williams et al. (2023)', '10.3389/fvets.2023.1040125', 'Williams DC, Haulena M, Dennison S, Waugh L, Goldstein T, Nutter F, Van Bonn B, Hoard V, Laxer KD, Buckmaster PS, Gulland FMD, Tharp B (2023). Pinniped electroencephalography: Methodology and findings in California sea lions (Zalophus californianus). Frontiers in Veterinary Science 10:1040125.'),
    'h25': ('Sasaki et al. (2025)', '10.1007/s10071-025-01971-0', 'Sasaki M, Kinoshita H, Konno A (2025). Do as I do imitation in a steller sea lion Eumetopias jubatus. Animal Cognition 28:49.'),
}

def expand(S, R, C, D):
    for key, (cite, doi, ref) in REFERENCES.items():
        C[key], D[key], R[key] = cite, doi, ref + ' https://doi.org/' + doi

    def replace(number, title, ref, image, panel, caption, body, extra=()):
        paragraphs = body.split('|')
        assert len(paragraphs) == 3
        S[number-2] = {
            'layout': 'figure-right', 'title': title, 'body': paragraphs,
            'figure': {'path': 'figures/'+image+'.png', 'kind': 'article',
                       'caption': C[ref]+', Fig. '+panel+'. '+caption,
                       'source_url': 'https://doi.org/'+D[ref]},
            'cite': C[ref], 'refs': [R[ref]],
            'transcript': paragraphs + list(extra),
        }

    replace(4, 'A folded cortex overlies a large cerebellum', 's16', 'Sawyer2016_f7abc', '7G–I', 'Dorsal, isometric, and ventral views of a juvenile sea-lion brain.',
        '**Neuroanatomy** is the organization of the nervous system and its structures. **Cerebral cortex** is the outer sheet of the cerebrum. Sawyer and colleagues examined a juvenile California sea-lion brain whose cortical surface contained numerous folds. **Gyri** are the raised folds; **sulci** are the grooves separating them. The two hemispheres had similar but nonidentical groove patterns.|The fixed specimen was 10.2 cm long and 10.1 cm wide near its posterior end, compared with 6.0 cm across the anterior portion. These are dimensions of the preserved juvenile specimen, rather than measurements of Ronan or a standard adult brain.|A large **cerebellum**, a brain structure involved in movement coordination, lay beneath the posterior cerebral region. The study localized sensory cortex using tissue stains and anatomical landmarks. Folding alone did not locate functional regions; microscopic organization supplied the boundaries of the somatosensory area.',
        ['The examined juvenile brain weighed 288.4 g after perfusion and immersion fixation. Preservation and developmental stage matter when comparing its dimensions with living adult animals.'])

    replace(5, 'Whisker follicles connect touch to the trigeminal nerve', 's16', 'Sawyer2016_f2acde', '2A–F', 'Whiskers, an innervated follicle, and sensory and motor roots.',
        '**Vibrissae** are specialized whiskers whose follicles receive sensory innervation. The examined sea lions had 38 whiskers arranged in six rows on each cheek pad. Their facial array provides many separate points at which contact or water movement can deform a whisker.|A stained follicle contained a blood-filled cavernous sinus and a deep vibrissal nerve entering its base. This structure differs from an ordinary coat-hair follicle. Whisker deformation is therefore delivered to an innervated sensory organ embedded in the skin rather than detected by the hair shaft itself.|The **trigeminal nerve** carries facial somatosensory signals, meaning information about touch and related bodily sensation. Its thick sensory root lay beside a separate, smaller motor root. **Axons** are nerve-cell fibers that conduct signals; **myelin** is their insulating sheath. Microscopy identified thinly and thickly myelinated axons in the pathway carrying facial information into the brainstem.')

    replace(6, 'Brainstem modules organize facial sensory input', 's16', 'Sawyer2016_f4ijk', '4I–K', 'Principal sensory nucleus stained for cells, metabolism, and VGLUT1.',
        'The **principal sensory trigeminal nucleus** is a brainstem relay for facial somatosensory information. In sea-lion tissue, this nucleus contained clusters separated by relatively cell-sparse partitions. Related modules also occurred in the spinal trigeminal nuclei, which extend the facial representation through the brainstem.|**Nissl staining** reveals neuronal cell bodies. **Cytochrome oxidase staining** marks metabolic organization, while vesicular glutamate transporter 1 staining identified dense afferent terminal regions. **Glutamate** is a neurotransmitter, a chemical signal released at synapses. This transporter packages it in presynaptic vesicles. The three preparations converged on a modular architecture instead of a uniform mass of tissue.|The arrangement resembled the facial whisker array, especially the six-row organization in the interpolaris subdivision. Individual sections did not yield an exact whisker-to-module assignment. The anatomical finding is a partitioned facial sensory representation, with dense incoming terminals concentrated within its modules.',
        ['Vesicular glutamate transporters package glutamate in presynaptic vesicles. VGLUT1 staining marks the organization of glutamatergic input terminals; staining is an anatomical assay, not a recording of sensory firing during behavior.'])

    replace(7, 'The thalamus separates face and body representations', 's16', 'Sawyer2016_f6bcd', '6B–D', 'Matched sections identify the somatosensory thalamic subdivisions.',
        'The **thalamus** contains relays between ascending sensory pathways and cerebral cortex. The sea-lion **ventral posterior nucleus** was distinguished from surrounding tissue by large neuronal cell bodies and dense staining for cytochrome oxidase and vesicular glutamate transporter 2.|Its **ventroposterior medial subdivision**, or VPM, occupied a large part of the nucleus and corresponds to facial representation in the mammalian somatosensory pathway. The neighboring **ventroposterior lateral subdivision**, or VPL, corresponds to bodily representation. Their boundaries changed across successive sections rather than forming identical shapes at every depth.|Lightly stained partitions divided the nucleus internally. The sea-lion preparation established these subdivisions anatomically, without a physiological point-by-point body map. Facial sensation thus has an extensive thalamic territory between its brainstem representation and the cortical sensory region.')

    replace(8, 'Sensory cortical layer 4 receives dense input', 's16', 'Sawyer2016_f8efg', '8E–G', 'Layer-specific metabolic, neuronal, and VGLUT2 staining.',
        '**Primary somatosensory cortex**, or S1, is a cerebral region receiving bodily sensory information. Sawyer and colleagues localized a presumptive S1 region just anterior to the major vertical fissure using its microscopic organization and position within the folded sea-lion cortex.|**Cortical layers** are bands that differ in neuronal populations and connections. In this region, layer 4 contained densely packed cells and stained strongly for cytochrome oxidase and vesicular glutamate transporter 2. Layer 5 was relatively cell-sparse, whereas layer 6 was thick and cell-dense.|The VGLUT2-rich layer identifies a concentration of glutamatergic input terminals associated with primary sensory cortex. Tissue organization therefore connected a macroscopically folded surface with a specific sensory territory. Reconstructing successive stained sections placed that territory relative to the coronal and suprasylvian sulci.')

    replace(9, 'Brain rhythms change with arousal state', 'e23', 'Williams2023_f2ab', '2A–B', 'Sea-lion EEG during wakefulness and slow-wave sleep.',
        '**Electroencephalography**, or EEG, records voltage fluctuations through electrodes near the head. Williams and colleagues adapted the electrode arrangement to California sea lions and identified patterns in neurologically normal animals alongside recordings from animals with neurological disease.|Wakeful recordings included low-amplitude **beta activity**, faster than 13 Hz, interspersed with **alpha activity** at 8–13 Hz. Slow-wave sleep contained high-amplitude **delta activity**, slower than 4 Hz, and sleep spindles around 12–14 Hz. The same nervous system can therefore produce different temporal activity patterns across states.|These EEG rhythms are electrical activity patterns, whereas Ronan’s entrainment is a measured relationship between movement and an external sound sequence. The distinction separates physiological frequency from behavioral beat keeping. Sedation and arousal were tracked because they altered the EEG state being interpreted.',
        ['Many animals received sedatives during electrode placement. These clinical recordings were not an auditory synchronization experiment or a natural-sleep survey. The comparison uses the paper’s neurologically normal wakeful and slow-wave examples.'])

    replace(10, 'Touch exploration changes with the sensory task', 'm21', 'Milne2021_f1ab', '1A–B', 'Lo explores texture and size with different whisker trajectories.',
        '**Active sensing** means moving a sensory organ to acquire information relevant to a task. Lo, a California sea lion, used different head and whisker movements when discriminating texture, size, or visual brightness. Blindfolds restricted the texture and size tasks to tactile exploration.|For texture, Lo swept laterally across the surfaces. For size, she moved toward the object edges and made larger whisker movements. Average whisker excursions were about 34° for texture and 47° for size, compared with 24° during visual brightness discrimination.|The target remained the intermediate stimulus among two distractors. A visual control reduced the need to explore by touch, and head and whisker movements declined. Task-specific movement therefore changed how the sensory surface was sampled, linking perceptual demands to the motor strategy used to solve them.',
        ['Movie 1 contains the original texture, size, and brightness trials in a single recording. Its segments are not counted as separate movies.'])

    replace(11, 'A learned command initiates sensory-guided choice', 'm21', 'Milne2021_f1c', '1C', 'Lo selects a brightness target with reduced tactile exploration.',
        'A **learned command** is a cue associated with a trained action or task. In Lo’s discrimination experiment, the trainer used “find it” to initiate exploration after the stimuli had been placed underwater. The command started a task whose solution still depended on information from the objects.|Lo indicated her choice by resting her nose on the selected stimulus for more than 3 s and retracting her whiskers. Correct choices produced a whistle followed by fish. The whistle served as a **conditioned reinforcer**, a previously learned signal marking success before the primary food reward arrived.|Stimulus positions changed between trials, so the same command could not be solved by approaching one permanent location. After learning, decisions during exploration took less than 1 s and accuracy approached complete target identification. The command controlled task initiation, while sensory discrimination controlled which object was selected.')

    replace(12, 'Whisker adjustments precede head corrections', 'm14', 'Milne2014_f1bc', '1b–c', 'Ball, head, and whisker positions during balancing.',
        'Ball balancing requires continuous adjustments as the supported object changes orientation. Milne and Grant recorded California sea lions named Gina, Anya, and Elmo performing this familiar trained action. The animals received ball-balancing commands and maintained the action until a trainer marked completion.|**Whisker asymmetry** describes the difference between average whisker angles on the two sides of the face. Changes in this measure followed ball orientation more closely and sooner than changes in head orientation. The reported average delays were approximately 27 ms for whiskers and 129 ms for the head.|Balancing therefore recruits control of the sensory array as well as movement of the larger support surface. Whisker movements need not merely follow the head passively. The supplied recording preserves the brief analyzed interval at its original speed, in which ball position and whisker configuration change together.',
        ['The source movie lasts 0.74 s. It is the original high-frame-rate analysis interval, not a long demonstration or a movie slowed for presentation. Use full-screen playback and replay if needed without changing its timing.'])

    replace(13, 'Banking turns recruit the hindflippers', 'l21', 'Leahy2021_f3abcd', '3A, E, I', 'Successive stages of a sea-lion banking turn.',
        'Sea lions propel ordinary forward swimming with their foreflippers, while the hindflippers can trail behind. A **banking turn** combines rolling the body with changing the swimming direction. Leahy and colleagues trained sea lions to complete 180° turns beneath an underwater viewing window.|At turn onset, the animal abducted its foreflippers, moving them away from the body, and rolled approximately 90°. The hindflippers spread and rotated, expanding their surface area. Their position behind the body’s center of gravity allows a hydrodynamic force to influence body orientation as well as the path of travel.|The hindflippers’ average **angle of attack**, their orientation relative to the approaching flow, was about 28° during turning. They remained spread during the maneuver and were adducted, brought together, as forward swimming resumed. Coordinated control therefore changes the role of an appendage with the behavioral requirement.',
        ['Movie 3 records a trained adult female making a left banking turn. This is coordinated locomotion, not evidence that she follows an auditory musical beat.'])

    replace(14, 'Leaping alternates propulsion and body stabilization', 'l21', 'Leahy2021_f1', '1', 'Sea-lion hindflipper geometry and spread configuration.',
        '**Porpoising** is a swimming pattern that repeatedly carries the body above and below the water surface. A trained California sea lion performed consecutive leaps while cameras recorded aerial and submerged phases. The full cycle lasted about 1.5 s in the analyzed captive performance.|The foreflippers generated propulsive strokes during submerged swimming. The hindflippers spread beneath the water and helped stabilize the posterior body region. At the fully aerial crest, the flippers were held against the body or folded rather than continuously generating force against water.|Water entry began with the nose along a curved path, followed by repositioning the foreflippers and hindflippers for the submerged phase. Hindflipper angle of attack during the analyzed submerged phase averaged about 15°. The coordinated cycle thus changes the timing and orientation of several body parts as the surrounding medium changes.',
        ['Movie 1 records the captive porpoising bout. The paper treats lift production as an interpretation of appendage geometry and measured motion, rather than measuring neural commands to the flippers.'])

    replace(15, 'Wild porpoising retains the coordinated movement pattern', 'l21', 'Leahy2021_f3ijkl', '3D, H, L', 'Changing flipper configuration during a maneuver.',
        'Wild California sea lions in Monterey Bay also executed repeated porpoising leaps. The field recordings and the trained-animal recordings supplied different contexts for the same broad locomotor pattern. Both involved alternating aerial movement with submerged propulsion and a changing hindflipper posture.|In the field sequence, the legs generally remained more extended during the aerial phase, and the hindflippers cleared the water. The reported average leap length was 0.81 body lengths and the aerial height was 0.06 body lengths. Expressing distances in body lengths permits comparison across differently sized animals.|The captive sea lion made longer and higher leaps and used a different entry angle. Training conditions can therefore change the scale of a movement without eliminating the coordinated pattern. The original field movie supplies the natural locomotor comparison; these measurements concern body control rather than synchronization to an acoustic pulse.')

    replace(16, 'Musical pulse guides movement beyond the training sound', 'c13', 'Cook2013_f4', '4A–B', 'Head-bob timing with Everybody and Boogie Wonderland.',
        'A musical recording contains overlapping instruments and events between the regular beats. Ronan coordinated her head movements with Everybody at about 108 bpm and Boogie Wonderland at 130 bpm. Keeping the repeated response organized required selecting a temporal regularity within this more complex acoustic material.|The songs had different exposure histories. Everybody received explicit training after earlier unsuccessful exposure. Boogie Wonderland had been heard briefly before the later transfer test, without that exposure producing entrained bobbing. Prior exposure and reinforced successful performance are distinct learning events.|After training at the native tempo of Boogie Wonderland, Ronan also followed altered versions spanning 104–143 bpm. The same musical material guided different movement rates. Flexibility across these versions links the trained action to the current pulse instead of one fixed speed learned from a familiar recording.')

    replace(32, 'Hama matches human actions beyond specific commands', 'h25', 'Hama2025_f2', '2', 'Action matching with familiar and unfamiliar human demonstrators.',
        'Hama, a Steller sea lion, had already learned a repertoire of actions through hand signals and verbal commands. Sasaki and colleagues trained a **do-as-I-do** response, in which a human action becomes the model for the animal’s action. Demonstrating “stand,” a head movement, or a tongue action replaced the usual specific cue.|The human initially paired demonstrations with familiar cues, then reduced those prompts. Hama subsequently matched most tested body actions with both a familiar trainer and an unfamiliar demonstrator. Several actions were familiar to her but had not been taught through the demonstration procedure.|Transfer separated general action matching from simply repeating the three demonstrations used during initial training. Performance also depended on what kind of action was attempted: novel body-oriented responses were easier than novel object manipulations. The acquired relationship linked observed body movement with selection from Hama’s own action repertoire.')

    replace(33, 'A Go cue separates remembering from immediate copying', 'h25', 'Hama2025_f5', '5', 'Visual barriers used after the human demonstration.',
        'In a second procedure, Hama watched a complete human demonstration while remaining still, then acted upon the verbal cue “Go.” **Response inhibition** is withholding an action that would otherwise occur. Learning to wait changed her earlier history of moving simultaneously with human demonstrations.|The tests included standing, spinning, lifting a hindflipper, and a kissing action. In a control condition, a barrier blocked visual contact with the demonstrator after the demonstration. Hama still produced the corresponding action when the demonstrator delivered the Go cue.|The final cue therefore specified when to respond, while the preceding demonstration specified what to do. Blocking the demonstrator during the response removed ongoing visual guidance as a requirement. This delayed command procedure differs from beat synchronization, where repeated sound events continually regulate the timing of an ongoing movement.')

    replace(34, 'Missing beats distinguish prediction from isolated reactions', 'c13', 'Cook2013_f3', '3A–B', 'Timing before and after omitted clicks.',
        'A reaction to each sound separately need not maintain a rhythm through silence. Cook and colleagues therefore omitted occasional beats from a 120 bpm sequence. Discrete clicks replaced the continuously modulated sound so that the missing event left a genuinely silent interval.|Ronan continued bobbing through the omitted events. Movements before and after the gap retained similar relationships to the expected beat locations. The repeating action continued while the next timing sound was absent instead of restarting only when another click arrived.|Continuation through an omission supports an ongoing timing process beyond isolated sound-triggered reactions. Later sounds can correct the position of the movement within the cycle. This combination of continuation and correction connects predictive timing with the perturbation experiments that independently changed beat position and tempo.')

    replace(35, 'Sound onsets and movement minima share a time base', 'c25', 'PMC12045976_f1', '1', 'Movement trajectories aligned with recorded sound onsets.',
        'A continuous head movement needs a defined event for comparison with a sound onset. Ronan’s selected landmark was the lowest point of each head bob. In the human comparison, it was the fullest downward extension of the arm. Using a repeatable landmark keeps the measured timing event consistent.|The interval between successive movement minima supplies the performed tempo. The position of each minimum relative to a sound onset supplies phase. Automated video tracking measured the trajectories while the audio track from the same recording identified sound events.|The 2025 experiment recorded at 240 frames per second, corresponding to roughly 4 ms between frames. This resolution allowed small anticipatory and delayed offsets to be measured within a cycle. A movement rate near the target can coexist with a nonzero offset from each sound, so both quantities characterize the coordination.')

    return S
